import React, { useState, useRef, useEffect } from 'react';

interface ColorGuideProps {
  onBack: () => void;
  onHome: () => void;
  onNextStep: (color: string) => void;
}

const ColorGuide: React.FC<ColorGuideProps> = ({ onBack, onHome, onNextStep }) => {
  const [selectedColor, setSelectedColor] = useState('#f9f6f1');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [extractedColors, setExtractedColors] = useState<string[]>([]);
  const [isImageLoaded, setIsImageLoaded] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const colorExamples = [
    { name: '따뜻한 베이지', code: '#f9f6f1', description: '패션, 뷰티 제품에 적합' },
    { name: '차분한 네이비', code: '#1e3a8a', description: '남성복, 정장류에 적합' },
    { name: '부드러운 핑크', code: '#fce7f3', description: '여성복, 화장품에 적합' },
    { name: '깔끔한 화이트', code: '#ffffff', description: '모든 제품에 범용적' },
    { name: '모던한 그레이', code: '#f3f4f6', description: '가전, 디지털 제품에 적합' },
    { name: '자연스러운 그린', code: '#ecfdf5', description: '식품, 건강제품에 적합' }
  ];

  // 이미지에서 색상 추출 함수
  const extractColorsFromImage = (imageData: ImageData) => {
    const colors: { [key: string]: number } = {};
    const data = imageData.data;

    // 이미지의 모든 픽셀을 스캔하여 색상 빈도 계산
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];

      // 색상을 그룹화하여 유사한 색상들을 하나로 묶기
      const roundedR = Math.round(r / 10) * 10;
      const roundedG = Math.round(g / 10) * 10;
      const roundedB = Math.round(b / 10) * 10;

      const colorKey = `#${roundedR.toString(16).padStart(2, '0')}${roundedG.toString(16).padStart(2, '0')}${roundedB.toString(16).padStart(2, '0')}`;

      if (colors[colorKey]) {
        colors[colorKey]++;
      } else {
        colors[colorKey] = 1;
      }
    }

    // 빈도순으로 정렬하고 상위 8개 색상 반환
    const sortedColors = Object.entries(colors)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 8)
      .map(([color]) => color);

    return sortedColors;
  };

  // 이미지 업로드 처리
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const imageUrl = e.target?.result as string;
        setUploadedImage(imageUrl);
        setIsImageLoaded(false);
      };
      reader.readAsDataURL(file);
    }
  };

  // 이미지 로드 완료 후 색상 추출
  useEffect(() => {
    if (uploadedImage && canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const img = new Image();

      img.onload = () => {
        // 캔버스 크기 설정 (최대 300x300으로 제한)
        const maxSize = 300;
        let { width, height } = img;

        if (width > height) {
          if (width > maxSize) {
            height = (height * maxSize) / width;
            width = maxSize;
          }
        } else {
          if (height > maxSize) {
            width = (width * maxSize) / height;
            height = maxSize;
          }
        }

        canvas.width = width;
        canvas.height = height;

        // 이미지를 캔버스에 그리기
        ctx?.drawImage(img, 0, 0, width, height);

        // 색상 추출
        const imageData = ctx?.getImageData(0, 0, width, height);
        if (imageData) {
          const colors = extractColorsFromImage(imageData);
          setExtractedColors(colors);
          if (colors.length > 0) {
            setSelectedColor(colors[0]); // 첫 번째 색상을 기본 선택
          }
        }

        setIsImageLoaded(true);
      };

      img.src = uploadedImage;
    }
  }, [uploadedImage]);

  // 캔버스 클릭으로 색상 선택
  const handleCanvasClick = (event: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    const ctx = canvas.getContext('2d');
    const pixel = ctx?.getImageData(x, y, 1, 1).data;

    if (pixel) {
      const color = `#${pixel[0].toString(16).padStart(2, '0')}${pixel[1].toString(16).padStart(2, '0')}${pixel[2].toString(16).padStart(2, '0')}`;
      setSelectedColor(color);
    }
  };

  return (
    <div>
      <div className="card">
        <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
          <button className="btn btn-secondary" onClick={onBack}>
            ← 뒤로가기
          </button>
          <button className="btn-home" onClick={onHome}>
            🏠 홈
          </button>
          <h2 style={{ marginLeft: '20px', fontSize: '1.6rem', color: '#1e293b' }}>
            🎨 배경 컬러 추천받기
          </h2>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            📸 이미지에서 컬러 추출하기
          </h3>

          <div className="card" style={{ textAlign: 'center', padding: '30px' }}>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              onChange={handleImageUpload}
              style={{ display: 'none' }}
            />

            {!uploadedImage ? (
              <div>
                <div style={{ fontSize: '3rem', marginBottom: '20px' }}>📁</div>
                <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>이미지 업로드</h4>
                <p style={{ color: '#64748b', marginBottom: '20px' }}>
                  제품 이미지를 업로드하면 자연스러운 배경 컬러를 추출해드려요
                </p>
                <button 
                  className="btn" 
                  onClick={() => fileInputRef.current?.click()}
                  style={{ 
                    fontSize: '1.1rem', 
                    padding: '12px 24px',
                    background: '#3b82f6',
                    color: 'white'
                  }}
                >
                  이미지 선택하기
                </button>
              </div>
            ) : (
              <div>
                <div style={{ marginBottom: '20px' }}>
                  <canvas
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    style={{
                      border: '2px solid #e5e7eb',
                      borderRadius: '12px',
                      cursor: 'crosshair',
                      maxWidth: '100%',
                      height: 'auto'
                    }}
                  />
                  <p style={{ color: '#64748b', fontSize: '0.9rem', marginTop: '10px' }}>
                    이미지를 클릭하여 원하는 색상을 선택하세요
                  </p>
                </div>

                {extractedColors.length > 0 && (
                  <div style={{ marginBottom: '20px' }}>
                    <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>추출된 팔레트</h4>
                    <div style={{ display: 'flex', gap: '10px', justifyContent: 'center', flexWrap: 'wrap' }}>
                      {extractedColors.map((color, index) => (
                        <div
                          key={index}
                          style={{
                            width: '40px',
                            height: '40px',
                            background: color,
                            borderRadius: '8px',
                            border: selectedColor === color ? '3px solid #3b82f6' : '2px solid #e5e7eb',
                            cursor: 'pointer',
                            transition: 'all 0.2s ease'
                          }}
                          onClick={() => setSelectedColor(color)}
                          title={color}
                        />
                      ))}
                    </div>
                  </div>
                )}

                <div style={{ marginBottom: '20px' }}>
                  <h4 style={{ marginBottom: '10px', color: '#1e293b' }}>선택된 색상</h4>
                  <div style={{ 
                    display: 'inline-block', 
                    width: '60px', 
                    height: '60px', 
                    background: selectedColor, 
                    borderRadius: '12px',
                    border: '2px solid #e5e7eb',
                    marginBottom: '10px'
                  }} />
                  <div style={{ color: '#64748b', fontWeight: 'bold' }}>{selectedColor}</div>
                </div>

                <button 
                  className="btn" 
                  onClick={() => {
                    setUploadedImage(null);
                    setExtractedColors([]);
                    setIsImageLoaded(false);
                  }}
                  style={{ marginRight: '10px' }}
                >
                  다른 이미지 선택
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            🎯 추천 배경 컬러 선택하기
          </h3>

          <div className="grid">
            {colorExamples.map((color, index) => (
              <div 
                key={index} 
                className="card" 
                style={{ 
                  padding: '20px', 
                  textAlign: 'center',
                  border: selectedColor === color.code ? '3px solid #3b82f6' : '1px solid #e5e7eb',
                  cursor: 'pointer',
                  transition: 'all 0.2s ease'
                }}
                onClick={() => setSelectedColor(color.code)}
              >
                <div 
                  style={{ 
                    width: '60px', 
                    height: '60px', 
                    borderRadius: '12px', 
                    background: color.code,
                    margin: '0 auto 15px',
                    border: '2px solid #e5e7eb'
                  }}
                />
                <h4 style={{ fontSize: '1.1rem', marginBottom: '8px', color: '#1e293b' }}>
                  {color.name}
                </h4>
                <p style={{ color: '#64748b', fontSize: '0.9rem', marginBottom: '10px' }}>
                  {color.description}
                </p>
                <div style={{ color: '#64748b', fontSize: '0.8rem', fontWeight: 'bold' }}>
                  {color.code}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            🎨 커스텀 컬러 선택
          </h3>

          <div className="card" style={{ textAlign: 'center', padding: '30px' }}>
            <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>직접 컬러 선택하기</h4>
            <input 
              type="color" 
              value={selectedColor}
              onChange={(e) => setSelectedColor(e.target.value)}
              style={{ 
                width: '100px', 
                height: '60px', 
                border: 'none', 
                borderRadius: '12px',
                cursor: 'pointer'
              }}
            />
            <div style={{ 
              marginTop: '15px', 
              padding: '10px', 
              background: selectedColor, 
              borderRadius: '8px',
              color: selectedColor === '#ffffff' ? '#000' : '#fff',
              fontWeight: 'bold'
            }}>
              선택된 컬러: {selectedColor}
            </div>
          </div>
        </div>

        <div className="mb-20" style={{ textAlign: 'center' }}>
          <button 
            className="btn" 
            style={{ 
              fontSize: '1.2rem', 
              padding: '15px 30px',
              background: '#3b82f6',
              color: 'white',
              border: 'none',
              borderRadius: '12px',
              cursor: 'pointer',
              fontWeight: 'bold'
            }}
            onClick={() => onNextStep(selectedColor)}
          >
            다음 단계: 텍스트 컬러 선택하기 →
          </button>
        </div>

        <div className="warning">
          <strong>💡 팁:</strong><br/>
          • 이미지를 업로드하면 자동으로 주요 색상들이 추출됩니다<br/>
          • 추출된 팔레트에서 원하는 색상을 클릭하거나, 이미지를 직접 클릭해서 정확한 색상을 선택하세요<br/>
          • 색상 선택 후 다음 단계로 넘어가면 텍스트 컬러를 추천받을 수 있습니다
        </div>
      </div>
    </div>
  );
};

export default ColorGuide;
